/**
 * @summary List Inner Circles
 */
export const getListCirclesUrl = (params?: ListCirclesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/circles?${stringifiedParams}`
    : `/api/circles`;
};

export const listCircles = async (
  params?: ListCirclesParams,
  options?: RequestInit,
): Promise<CirclesList> => {
  return customFetch<CirclesList>(getListCirclesUrl(params), {
    ...options,
    method: "GET",
  });
};

